(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit61-trap-c4-basic-1"]={"id":"unit61-trap-c4-basic-1","unitId":"6-1","chapterIds":["6-1"],"unitType":"basic","group":"6-1단원 · 선지 변형 유형 · 비교","name":"기본 OX 1","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit61","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"비교","parts":[{"name":"U61-H01-02-B1 · 맞닿아 있다의 뜻","items":[{"paragraphCount":1,"readingLabel":"1문단 · 핵심 읽기 2/5단계","sourceLabel":"김효정, 「재생과 공존」 읽기 · 1문단","passage":"[핵심 문장 · 1문단]\n이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"‘맞닿아 있다’는 서로 바로 이어져 있다는 뜻이고, ‘전 지구적 문제’는 지구 전체의 문제라는 뜻이다.\n근거: “이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.”","evidence":{"title":"맞닿아 있다의 뜻","statement":"늘어난 에너지 소비량은 기후 변화라는 지구 전체의 문제와 바로 이어져 있다.","explanation":"‘맞닿아 있다’는 서로 바로 이어져 있다는 뜻이고, ‘전 지구적 문제’는 지구 전체의 문제라는 뜻이다.\n근거: “이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.”","valid":["E01:3"],"sources":[{"id":"E01","title":"김효정, 「재생과 공존」 읽기","label":"1문단","sentences":[{"id":"E01:3","text":"이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.","paragraph":0,"memberIds":["E01:3"],"topic":"이렇게 늘어난 에너지의 대부분은 석탄과 석유이다. 그리고 이것은 지구 전체의 문제인 기후 변화와 바로 이어져 있다(맞닿아 있다)."}]}]},"shortComparison":true,"focusQuotes":[{"id":"E01:3","text":"이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U61-H01-02-B1","type":"ox","answer":"O","changed":"늘어난 에너지 소비량은 기후 변화라는 지구 전체의 문제와 바로 이어져 있다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"맞닿아 있다의 뜻","hintGuide":"‘맞닿아 있다’와 ‘전 지구적’을 쉬운 말로 바꾸어 보세요.","synthesis":false,"editorSourceVersion":"879a7b2a177d3117ec6ca0006e291b54f9221eed9c86e9d3e7858887bcae7688"}]},{"name":"U61-E01-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"1문단 · 새 예시 적용","sourceLabel":"김효정, 「재생과 공존」 읽기 · 1문단","passage":"[김효정, 「재생과 공존」 읽기 · 1문단]\n인류는 산업 혁명을 기점으로 석탄과 함께 석유를 주 에너지원으로 사용하고 있다. 인간의 경제 활동이 활발해지고 산업이 발전하면서 에너지 사용량은 점점 늘어나게 되었는데, 2016년 기준으로 전 세계의 1차 에너지 소비량은 100년 전에 비하면 약 10배 늘어났다. 이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다. 석탄과 석유에 의존하는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 발생시키고, 이때 발생한 이산화 탄소는 지구의 온실 효과를 가져와 기후 변화를 일으키기 때문이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준이가 학교 매점의 음료 판매량을 그래프로 그려 보니, 올해는 10년 전보다 약 10배 많이 팔렸다. 늘어난 음료의 대부분은 플라스틱병 음료였다. 플라스틱병은 다 마시고 나면 쓰레기가 되므로, 판매량이 늘어난 것은 학교의 쓰레기 문제와 바로 이어져 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"늘어난 음료의 대부분인 플라스틱병은 늘어난 에너지 소비량의 대부분인 석탄과 석유에, 쓰레기 문제는 기후 변화에 대응한다.\n근거: “인간의 경제 활동이 활발해지고 산업이 발전하면서 에너지 사용량은 점점 늘어나게 되었는데, 2016년 기준으로 전 세계의 1차 에너지 소비량은 100년 전에 비하면 약 10배 늘어났다.” “이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.” “석탄과 석유에 의존하는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 발생시키고, 이때 발생한 이산화 탄소는 지구의 온실 효과를 가져와 기후 변화를 일으키기 때문이다.”\n1문단에서 확인할 수 있어요.","evidence":{"title":"매점의 플라스틱병 음료","statement":"플라스틱병은 늘어난 양의 대부분인 석탄·석유에 해당한다.","explanation":"늘어난 음료의 대부분인 플라스틱병은 늘어난 에너지 소비량의 대부분인 석탄과 석유에, 쓰레기 문제는 기후 변화에 대응한다.\n근거: “인간의 경제 활동이 활발해지고 산업이 발전하면서 에너지 사용량은 점점 늘어나게 되었는데, 2016년 기준으로 전 세계의 1차 에너지 소비량은 100년 전에 비하면 약 10배 늘어났다.” “이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.” “석탄과 석유에 의존하는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 발생시키고, 이때 발생한 이산화 탄소는 지구의 온실 효과를 가져와 기후 변화를 일으키기 때문이다.”\n1문단에서 확인할 수 있어요.","valid":["E01:2","E01:3","E01:4"],"sources":[{"id":"E01","title":"김효정, 「재생과 공존」 읽기","label":"1문단","sentences":[{"id":"E01:1","text":"인류는 산업 혁명을 기점으로 석탄과 함께 석유를 주 에너지원으로 사용하고 있다.","paragraph":0,"memberIds":["E01:1"],"topic":"사람들은 산업 혁명 때부터 석탄과 석유를 가장 많이 쓰는 에너지의 원료(주 에너지원)로 사용하고 있다."},{"id":"E01:2","text":"인간의 경제 활동이 활발해지고 산업이 발전하면서 에너지 사용량은 점점 늘어나게 되었는데, 2016년 기준으로 전 세계의 1차 에너지 소비량은 100년 전에 비하면 약 10배 늘어났다.","paragraph":0,"memberIds":["E01:2"],"topic":"사람들의 경제 활동이 많아지고 산업이 발전하면서 에너지를 쓰는 양이 점점 늘었다. 2016년에 전 세계가 쓴 1차 에너지의 양은 100년 전보다 약 10배 많다."},{"id":"E01:3","text":"이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.","paragraph":0,"memberIds":["E01:3"],"topic":"이렇게 늘어난 에너지의 대부분은 석탄과 석유이다. 그리고 이것은 지구 전체의 문제인 기후 변화와 바로 이어져 있다(맞닿아 있다)."},{"id":"E01:4","text":"석탄과 석유에 의존하는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 발생시키고, 이때 발생한 이산화 탄소는 지구의 온실 효과를 가져와 기후 변화를 일으키기 때문이다.","paragraph":0,"memberIds":["E01:4"],"topic":"왜냐하면 석탄과 석유로 얻는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 내보내기 때문이다. 이 이산화 탄소가 지구의 온실 효과를 가져오고, 그것이 기후 변화를 일으킨다."}]}]},"examplePractice":true,"id":"U61-E01-B1","type":"ox","answer":"O","changed":"플라스틱병은 늘어난 양의 대부분인 석탄·석유에 해당한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"3b38f418a8605c6cf9f89a0c79c44de6ef5fc16e39b9f1bfb859248c3ee7a77d"}]},{"name":"U61-E01-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"1문단 · 새 예시 적용","sourceLabel":"김효정, 「재생과 공존」 읽기 · 1문단","passage":"[김효정, 「재생과 공존」 읽기 · 1문단]\n인류는 산업 혁명을 기점으로 석탄과 함께 석유를 주 에너지원으로 사용하고 있다. 인간의 경제 활동이 활발해지고 산업이 발전하면서 에너지 사용량은 점점 늘어나게 되었는데, 2016년 기준으로 전 세계의 1차 에너지 소비량은 100년 전에 비하면 약 10배 늘어났다. 이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다. 석탄과 석유에 의존하는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 발생시키고, 이때 발생한 이산화 탄소는 지구의 온실 효과를 가져와 기후 변화를 일으키기 때문이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준이가 학교 매점의 음료 판매량을 그래프로 그려 보니, 올해는 10년 전보다 약 10배 많이 팔렸다. 늘어난 음료의 대부분은 플라스틱병 음료였다. 플라스틱병은 다 마시고 나면 쓰레기가 되므로, 판매량이 늘어난 것은 학교의 쓰레기 문제와 바로 이어져 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"늘어난 음료의 대부분인 플라스틱병은 늘어난 에너지 소비량의 대부분인 석탄과 석유에, 쓰레기 문제는 기후 변화에 대응한다.\n근거: “인간의 경제 활동이 활발해지고 산업이 발전하면서 에너지 사용량은 점점 늘어나게 되었는데, 2016년 기준으로 전 세계의 1차 에너지 소비량은 100년 전에 비하면 약 10배 늘어났다.” “이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.” “석탄과 석유에 의존하는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 발생시키고, 이때 발생한 이산화 탄소는 지구의 온실 효과를 가져와 기후 변화를 일으키기 때문이다.”\n1문단에서 확인할 수 있어요.","evidence":{"title":"매점의 플라스틱병 음료","statement":"플라스틱병은 늘어난 양의 대부분인 석탄·석유에 해당한다.","explanation":"늘어난 음료의 대부분인 플라스틱병은 늘어난 에너지 소비량의 대부분인 석탄과 석유에, 쓰레기 문제는 기후 변화에 대응한다.\n근거: “인간의 경제 활동이 활발해지고 산업이 발전하면서 에너지 사용량은 점점 늘어나게 되었는데, 2016년 기준으로 전 세계의 1차 에너지 소비량은 100년 전에 비하면 약 10배 늘어났다.” “이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.” “석탄과 석유에 의존하는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 발생시키고, 이때 발생한 이산화 탄소는 지구의 온실 효과를 가져와 기후 변화를 일으키기 때문이다.”\n1문단에서 확인할 수 있어요.","valid":["E01:2","E01:3","E01:4"],"sources":[{"id":"E01","title":"김효정, 「재생과 공존」 읽기","label":"1문단","sentences":[{"id":"E01:1","text":"인류는 산업 혁명을 기점으로 석탄과 함께 석유를 주 에너지원으로 사용하고 있다.","paragraph":0,"memberIds":["E01:1"],"topic":"사람들은 산업 혁명 때부터 석탄과 석유를 가장 많이 쓰는 에너지의 원료(주 에너지원)로 사용하고 있다."},{"id":"E01:2","text":"인간의 경제 활동이 활발해지고 산업이 발전하면서 에너지 사용량은 점점 늘어나게 되었는데, 2016년 기준으로 전 세계의 1차 에너지 소비량은 100년 전에 비하면 약 10배 늘어났다.","paragraph":0,"memberIds":["E01:2"],"topic":"사람들의 경제 활동이 많아지고 산업이 발전하면서 에너지를 쓰는 양이 점점 늘었다. 2016년에 전 세계가 쓴 1차 에너지의 양은 100년 전보다 약 10배 많다."},{"id":"E01:3","text":"이렇게 늘어난 에너지 소비량의 대부분은 석탄과 석유가 차지하고 있으며 이는 기후 변화라는 전 지구적 문제와 맞닿아 있다.","paragraph":0,"memberIds":["E01:3"],"topic":"이렇게 늘어난 에너지의 대부분은 석탄과 석유이다. 그리고 이것은 지구 전체의 문제인 기후 변화와 바로 이어져 있다(맞닿아 있다)."},{"id":"E01:4","text":"석탄과 석유에 의존하는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 발생시키고, 이때 발생한 이산화 탄소는 지구의 온실 효과를 가져와 기후 변화를 일으키기 때문이다.","paragraph":0,"memberIds":["E01:4"],"topic":"왜냐하면 석탄과 석유로 얻는 화석 에너지는 연료를 태우는 동안 이산화 탄소를 내보내기 때문이다. 이 이산화 탄소가 지구의 온실 효과를 가져오고, 그것이 기후 변화를 일으킨다."}]}]},"examplePractice":true,"id":"U61-E01-B2","type":"ox","answer":"X","changed":"플라스틱병은 기후 변화를 줄이는 재생 에너지에 해당한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":7,"end":26,"before":"기후 변화를 줄이는 재생 에너지에 ","after":"늘어난 양의 대부분인 석탄·석유에 "}],"editorSourceVersion":"c5532b0f5244fb189289d809f28d2da7e8b34fa99606de71153d3fc68e6ca33f"}]},{"name":"U61-H02-05-B1 · 2문단의 핵심","items":[{"paragraphCount":1,"readingLabel":"2문단 · 핵심 읽기 5/5단계","sourceLabel":"김효정, 「재생과 공존」 읽기 · 2문단","passage":"[문단 전체 · 2문단]\n온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다. 자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다. 21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다. 이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다. 인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"2문단은 필요한 온실 효과와 지나친 이산화 탄소를 대조하고, 에너지 사용이 공존을 위협한다고 정리한다.\n근거: “자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.” “이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다.” “인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.”","evidence":{"title":"2문단의 핵심","statement":"자연적인 온실 효과는 필요하지만, 화석 연료의 막대한 이산화 탄소가 기온과 해수면을 높여 공존을 위협한다.","explanation":"2문단은 필요한 온실 효과와 지나친 이산화 탄소를 대조하고, 에너지 사용이 공존을 위협한다고 정리한다.\n근거: “자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.” “이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다.” “인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.”","valid":["E02:2","E02:4","E02:5"],"sources":[{"id":"E02","title":"김효정, 「재생과 공존」 읽기","label":"2문단","sentences":[{"id":"E02:1","text":"온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다.","paragraph":0,"memberIds":["E02:1"],"topic":"온실 효과는 공기 속의 수증기, 이산화 탄소, 메탄 같은 기체가, 지구에서 우주로 빠져나가는 열(파장이 긴 원적외선)을 지구 표면 가까이에 붙잡아 두는 것이다."},{"id":"E02:2","text":"자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.","paragraph":0,"memberIds":["E02:2"],"topic":"자연적인 온실 효과는 지구 온도를 생물이 살기 알맞은 15도로 지켜 주는 꼭 필요한 것이다. 하지만 화석 연료에서 나온 엄청난 양의 이산화 탄소는 1950년대부터 2005년까지 지구 평균 표면 온도를 약 0.7도 올린 것으로 짐작된다(추정된다)."},{"id":"E02:3","text":"21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다.","paragraph":0,"memberIds":["E02:3"],"topic":"21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다."},{"id":"E02:4","text":"이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다.","paragraph":0,"memberIds":["E02:4"],"topic":"이렇게 지구 표면 온도가 바뀌면 바닷물이 데워져 부피가 늘어나(열팽창) 바다 높이(해수면)가 약 0.5 m 올라간다. 그리고 2100년 이후, 어쩌면 그보다 더 일찍 남극의 빙하가 녹아 해수면이 더 올라갈 것으로 예상된다."},{"id":"E02:5","text":"인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.","paragraph":0,"memberIds":["E02:5"],"topic":"결국 사람들이 에너지를 만들고 쓰는 일이 우리와 지구가 함께 살아가는 것(공존)을 위험하게 만드는 일이 된다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"E02:2","text":"자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다."},{"id":"E02:4","text":"이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다."},{"id":"E02:5","text":"인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U61-H02-05-B1","type":"ox","answer":"O","changed":"자연적인 온실 효과는 필요하지만, 화석 연료의 막대한 이산화 탄소가 기온과 해수면을 높여 공존을 위협한다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"2문단의 핵심","hintGuide":"필요한 것과 문제가 되는 것을 나누어 보고, 끝 문장이 무엇을 정리하는지 보세요.","synthesis":true,"editorSourceVersion":"5beb35363e6e30fd9a81e73aaef100e5d2057fb9d6b336c3a26374134c6b2a8b"}]},{"name":"U61-H02-05-B2 · 온실 효과에 대한 2문단의 판단","items":[{"paragraphCount":1,"readingLabel":"2문단 · 핵심 읽기 5/5단계","sourceLabel":"김효정, 「재생과 공존」 읽기 · 2문단","passage":"[문단 전체 · 2문단]\n온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다. 자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다. 21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다. 이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다. 인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"자연적인 온실 효과는 15도 유지에 필요한 요소이다. 문제는 화석 연료에서 나온 막대한 이산화 탄소이다.\n근거: “자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.”","evidence":{"title":"온실 효과에 대한 2문단의 판단","statement":"2문단은 자연적인 온실 효과는 필요하지만 막대한 이산화 탄소가 문제라고 설명한다.","explanation":"자연적인 온실 효과는 15도 유지에 필요한 요소이다. 문제는 화석 연료에서 나온 막대한 이산화 탄소이다.\n근거: “자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.”","valid":["E02:2"],"sources":[{"id":"E02","title":"김효정, 「재생과 공존」 읽기","label":"2문단","sentences":[{"id":"E02:1","text":"온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다.","paragraph":0,"memberIds":["E02:1"],"topic":"온실 효과는 공기 속의 수증기, 이산화 탄소, 메탄 같은 기체가, 지구에서 우주로 빠져나가는 열(파장이 긴 원적외선)을 지구 표면 가까이에 붙잡아 두는 것이다."},{"id":"E02:2","text":"자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.","paragraph":0,"memberIds":["E02:2"],"topic":"자연적인 온실 효과는 지구 온도를 생물이 살기 알맞은 15도로 지켜 주는 꼭 필요한 것이다. 하지만 화석 연료에서 나온 엄청난 양의 이산화 탄소는 1950년대부터 2005년까지 지구 평균 표면 온도를 약 0.7도 올린 것으로 짐작된다(추정된다)."},{"id":"E02:3","text":"21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다.","paragraph":0,"memberIds":["E02:3"],"topic":"21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다."},{"id":"E02:4","text":"이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다.","paragraph":0,"memberIds":["E02:4"],"topic":"이렇게 지구 표면 온도가 바뀌면 바닷물이 데워져 부피가 늘어나(열팽창) 바다 높이(해수면)가 약 0.5 m 올라간다. 그리고 2100년 이후, 어쩌면 그보다 더 일찍 남극의 빙하가 녹아 해수면이 더 올라갈 것으로 예상된다."},{"id":"E02:5","text":"인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.","paragraph":0,"memberIds":["E02:5"],"topic":"결국 사람들이 에너지를 만들고 쓰는 일이 우리와 지구가 함께 살아가는 것(공존)을 위험하게 만드는 일이 된다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"E02:2","text":"자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U61-H02-05-B2","type":"ox","answer":"X","changed":"2문단은 온실 효과가 무조건 나쁘므로 모두 없애야 한다고 설명한다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","claimEdits":[{"start":0,"end":5,"before":"2문단은 ","after":"2문단은 자연적인 "},{"start":8,"end":32,"before":"효과가 무조건 나쁘므로 모두 없애야 한다고 ","after":"효과는 필요하지만 막대한 이산화 탄소가 문제라고 "}],"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"온실 효과에 대한 2문단의 판단","hintGuide":"‘필요한 요소이지만’ 앞뒤에 무엇이 오는지 보세요.","synthesis":true,"editorSourceVersion":"4f1cddf55cea529c96252bf9e454ccf0df52c0ecea0ba156c00ea61667170c48"}]},{"name":"U61-E02-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"2문단 · 새 예시 적용","sourceLabel":"김효정, 「재생과 공존」 읽기 · 2문단","passage":"[김효정, 「재생과 공존」 읽기 · 2문단]\n온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다. 자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다. 21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다. 이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다. 인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n겨울밤, 서윤이는 이불 한 장을 덮고 잔다. 몸에서 나온 열을 이불이 알맞게 붙잡아 줘서 따뜻하게 잘 수 있다. 그런데 이불을 다섯 장이나 겹쳐 덮었더니 열이 거의 빠져나가지 못해 너무 더워졌고, 서윤이는 땀을 흘리며 잠을 설쳤다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"알맞게 열을 붙잡는 이불 한 장은 지구 온도를 15도로 유지하는 자연적인 온실 효과에, 지나치게 겹친 다섯 장은 평균 표면 온도를 높인 막대한 이산화 탄소에 대응한다.\n근거: “온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다.” “자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"겨울 이불","statement":"이불 한 장은 꼭 필요한 자연적인 온실 효과와 닮았다.","explanation":"알맞게 열을 붙잡는 이불 한 장은 지구 온도를 15도로 유지하는 자연적인 온실 효과에, 지나치게 겹친 다섯 장은 평균 표면 온도를 높인 막대한 이산화 탄소에 대응한다.\n근거: “온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다.” “자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.”\n2문단에서 확인할 수 있어요.","valid":["E02:1","E02:2"],"sources":[{"id":"E02","title":"김효정, 「재생과 공존」 읽기","label":"2문단","sentences":[{"id":"E02:1","text":"온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다.","paragraph":0,"memberIds":["E02:1"],"topic":"온실 효과는 공기 속의 수증기, 이산화 탄소, 메탄 같은 기체가, 지구에서 우주로 빠져나가는 열(파장이 긴 원적외선)을 지구 표면 가까이에 붙잡아 두는 것이다."},{"id":"E02:2","text":"자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.","paragraph":0,"memberIds":["E02:2"],"topic":"자연적인 온실 효과는 지구 온도를 생물이 살기 알맞은 15도로 지켜 주는 꼭 필요한 것이다. 하지만 화석 연료에서 나온 엄청난 양의 이산화 탄소는 1950년대부터 2005년까지 지구 평균 표면 온도를 약 0.7도 올린 것으로 짐작된다(추정된다)."},{"id":"E02:3","text":"21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다.","paragraph":0,"memberIds":["E02:3"],"topic":"21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다."},{"id":"E02:4","text":"이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다.","paragraph":0,"memberIds":["E02:4"],"topic":"이렇게 지구 표면 온도가 바뀌면 바닷물이 데워져 부피가 늘어나(열팽창) 바다 높이(해수면)가 약 0.5 m 올라간다. 그리고 2100년 이후, 어쩌면 그보다 더 일찍 남극의 빙하가 녹아 해수면이 더 올라갈 것으로 예상된다."},{"id":"E02:5","text":"인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.","paragraph":0,"memberIds":["E02:5"],"topic":"결국 사람들이 에너지를 만들고 쓰는 일이 우리와 지구가 함께 살아가는 것(공존)을 위험하게 만드는 일이 된다."}]}]},"examplePractice":true,"id":"U61-E02-B1","type":"ox","answer":"O","changed":"이불 한 장은 꼭 필요한 자연적인 온실 효과와 닮았다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"fc23495e7d997829ba5da25bb8112553fd1970c319f9494ace02ac43c8ca3191"}]},{"name":"U61-E02-B2 · 비교","items":[{"paragraphCount":2,"readingLabel":"2문단 · 새 예시 적용","sourceLabel":"김효정, 「재생과 공존」 읽기 · 2문단","passage":"[김효정, 「재생과 공존」 읽기 · 2문단]\n온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다. 자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다. 21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다. 이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다. 인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n겨울밤, 서윤이는 이불 한 장을 덮고 잔다. 몸에서 나온 열을 이불이 알맞게 붙잡아 줘서 따뜻하게 잘 수 있다. 그런데 이불을 다섯 장이나 겹쳐 덮었더니 열이 거의 빠져나가지 못해 너무 더워졌고, 서윤이는 땀을 흘리며 잠을 설쳤다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"알맞게 열을 붙잡는 이불 한 장은 지구 온도를 15도로 유지하는 자연적인 온실 효과에, 지나치게 겹친 다섯 장은 평균 표면 온도를 높인 막대한 이산화 탄소에 대응한다.\n근거: “온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다.” “자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"겨울 이불","statement":"이불 한 장은 꼭 필요한 자연적인 온실 효과와 닮았다.","explanation":"알맞게 열을 붙잡는 이불 한 장은 지구 온도를 15도로 유지하는 자연적인 온실 효과에, 지나치게 겹친 다섯 장은 평균 표면 온도를 높인 막대한 이산화 탄소에 대응한다.\n근거: “온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다.” “자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.”\n2문단에서 확인할 수 있어요.","valid":["E02:1","E02:2"],"sources":[{"id":"E02","title":"김효정, 「재생과 공존」 읽기","label":"2문단","sentences":[{"id":"E02:1","text":"온실 효과는 대기 중의 수증기, 이산화 탄소, 메탄 등이 지구에서 우주로 방출되는 파장이 긴 원적외선을 지구 표면 가까이에 가두는 것이다.","paragraph":0,"memberIds":["E02:1"],"topic":"온실 효과는 공기 속의 수증기, 이산화 탄소, 메탄 같은 기체가, 지구에서 우주로 빠져나가는 열(파장이 긴 원적외선)을 지구 표면 가까이에 붙잡아 두는 것이다."},{"id":"E02:2","text":"자연적인 온실 효과는 지구의 온도를 생명 활동에 적합한 15도로 유지하는 데 필요한 요소이지만, 화석 연료에서 방출되는 막대한 이산화 탄소는 1950년대부터 2005년까지 지구의 평균 표면 온도를 약 0.7도 증가시킨 것으로 추정된다.","paragraph":0,"memberIds":["E02:2"],"topic":"자연적인 온실 효과는 지구 온도를 생물이 살기 알맞은 15도로 지켜 주는 꼭 필요한 것이다. 하지만 화석 연료에서 나온 엄청난 양의 이산화 탄소는 1950년대부터 2005년까지 지구 평균 표면 온도를 약 0.7도 올린 것으로 짐작된다(추정된다)."},{"id":"E02:3","text":"21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다.","paragraph":0,"memberIds":["E02:3"],"topic":"21세기 말에는 지구 평균 표면 온도가 약 1.4~5.8도 높아질 것으로 계산하고 있다."},{"id":"E02:4","text":"이렇게 지구 표면 온도가 변화하면 바닷물의 열팽창으로 해수면의 높이가 약 0.5 m 상승하고 2100년 이후 혹은 그보다 더 빠른 시기에는 남극의 빙하가 녹아 해수면이 더 상승할 것으로 예상된다.","paragraph":0,"memberIds":["E02:4"],"topic":"이렇게 지구 표면 온도가 바뀌면 바닷물이 데워져 부피가 늘어나(열팽창) 바다 높이(해수면)가 약 0.5 m 올라간다. 그리고 2100년 이후, 어쩌면 그보다 더 일찍 남극의 빙하가 녹아 해수면이 더 올라갈 것으로 예상된다."},{"id":"E02:5","text":"인류가 에너지를 만들고 사용하는 것이 우리와 지구의 공존을 위협하는 일이 되는 것이다.","paragraph":0,"memberIds":["E02:5"],"topic":"결국 사람들이 에너지를 만들고 쓰는 일이 우리와 지구가 함께 살아가는 것(공존)을 위험하게 만드는 일이 된다."}]}]},"examplePractice":true,"id":"U61-E02-B2","type":"ox","answer":"X","changed":"이불 한 장은 화석 연료의 막대한 이산화 탄소와 닮았다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":8,"end":27,"before":"화석 연료의 막대한 이산화 탄소와 ","after":"꼭 필요한 자연적인 온실 효과와 "}],"editorSourceVersion":"8ebc8ee38e62aae9ee346b1726a41b27dffa4779f9dc2fd94e775ebc186f77b6"}]},{"name":"U61-H03-02-B1 · 햇빛과 태양 복사 에너지","items":[{"paragraphCount":1,"readingLabel":"3문단 · 핵심 읽기 2/5단계","sourceLabel":"김효정, 「재생과 공존」 읽기 · 3문단","passage":"[핵심 문장 · 3문단]\n이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"‘햇빛, 즉 지구에 도달하는 태양 복사 에너지’에서 ‘즉’은 앞말을 다시 풀어 말한다.\n근거: “이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다.”","evidence":{"title":"햇빛과 태양 복사 에너지","statement":"이 글에서 햇빛은 지구에 도달하는 태양 복사 에너지를 가리킨다.","explanation":"‘햇빛, 즉 지구에 도달하는 태양 복사 에너지’에서 ‘즉’은 앞말을 다시 풀어 말한다.\n근거: “이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다.”","valid":["E03:3"],"sources":[{"id":"E03","title":"김효정, 「재생과 공존」 읽기","label":"3문단","sentences":[{"id":"E03:3","text":"이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다.","paragraph":0,"memberIds":["E03:3"],"topic":"그중에서도 햇빛, 다시 말해 지구에 도착하는 태양 복사 에너지는 약 30 %가 우주로 다시 튕겨 나가고(반사되고) 나머지 70 % 정도를 쓸 수 있다. 그래서 아주 매력적인 재생 에너지라고 할 수 있다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"E03:3","text":"이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U61-H03-02-B1","type":"ox","answer":"O","changed":"이 글에서 햇빛은 지구에 도달하는 태양 복사 에너지를 가리킨다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"햇빛과 태양 복사 에너지","hintGuide":"‘즉’ 앞과 뒤가 같은 것을 가리키는지 보세요.","synthesis":false,"editorSourceVersion":"e395b8882fd72615b46822a24fd0ad108ba73ebab7fcbb5ba973c513bfe47ebd"}]},{"name":"U61-H03-05-B1 · 3문단의 핵심","items":[{"paragraphCount":1,"readingLabel":"3문단 · 핵심 읽기 5/5단계","sourceLabel":"김효정, 「재생과 공존」 읽기 · 3문단","passage":"[문단 전체 · 3문단]\n이제 인류는 공존을 위해 기존의 화석 에너지를 대체할 방법으로 재생 에너지를 사용하려고 한다. 재생 에너지는 재생이 가능한 에너지로서 햇빛, 물, 지열, 강수, 생물 유기체 등에 포함된 에너지를 변환해 이용하는 에너지를 말한다. 이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다. 이 양은 2009년 기준으로 전체 화석 연료와 원자력 에너지 사용량의 8,200배에 해당한다. 태양 복사를 에너지로 사용하는 방법에는 태양열을 직접 흡수해서 물을 데우거나 난방으로 사용하는 방법, 태양열 발전소를 이용하는 방법, 그리고 태양 전지를 만들어 사용하는 방법이 있다. 태양 전지는 태양 에너지를 직접 전기로 변환하는 장치로, 가장 이상적인 에너지 변환 장치 중 하나라고 할 수 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"3문단은 화석 에너지를 대체할 재생 에너지를 소개하고, 그중 햇빛의 쓸 수 있는 양이 매우 많다고 설명한다.\n근거: “이제 인류는 공존을 위해 기존의 화석 에너지를 대체할 방법으로 재생 에너지를 사용하려고 한다.” “이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다.” “이 양은 2009년 기준으로 전체 화석 연료와 원자력 에너지 사용량의 8,200배에 해당한다.”","evidence":{"title":"3문단의 핵심","statement":"인류는 공존을 위해 화석 에너지 대신 재생 에너지, 그중에서도 쓸 수 있는 양이 많은 햇빛을 이용하려 한다.","explanation":"3문단은 화석 에너지를 대체할 재생 에너지를 소개하고, 그중 햇빛의 쓸 수 있는 양이 매우 많다고 설명한다.\n근거: “이제 인류는 공존을 위해 기존의 화석 에너지를 대체할 방법으로 재생 에너지를 사용하려고 한다.” “이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다.” “이 양은 2009년 기준으로 전체 화석 연료와 원자력 에너지 사용량의 8,200배에 해당한다.”","valid":["E03:1","E03:3","E03:4"],"sources":[{"id":"E03","title":"김효정, 「재생과 공존」 읽기","label":"3문단","sentences":[{"id":"E03:1","text":"이제 인류는 공존을 위해 기존의 화석 에너지를 대체할 방법으로 재생 에너지를 사용하려고 한다.","paragraph":0,"memberIds":["E03:1"],"topic":"이제 사람들은 지구와 함께 살아가기(공존) 위해, 지금까지 써 온 화석 에너지를 대신할 방법으로 재생 에너지를 쓰려고 한다."},{"id":"E03:2","text":"재생 에너지는 재생이 가능한 에너지로서 햇빛, 물, 지열, 강수, 생물 유기체 등에 포함된 에너지를 변환해 이용하는 에너지를 말한다.","paragraph":0,"memberIds":["E03:2"],"topic":"재생 에너지는 다시 생겨날 수 있는(재생이 가능한) 에너지이다. 햇빛, 물, 땅속의 열(지열), 비·눈(강수), 생물(생물 유기체) 등에 들어 있는 에너지를 바꾸어(변환해) 쓰는 에너지를 말한다."},{"id":"E03:3","text":"이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다.","paragraph":0,"memberIds":["E03:3"],"topic":"그중에서도 햇빛, 다시 말해 지구에 도착하는 태양 복사 에너지는 약 30 %가 우주로 다시 튕겨 나가고(반사되고) 나머지 70 % 정도를 쓸 수 있다. 그래서 아주 매력적인 재생 에너지라고 할 수 있다."},{"id":"E03:4","text":"이 양은 2009년 기준으로 전체 화석 연료와 원자력 에너지 사용량의 8,200배에 해당한다.","paragraph":0,"memberIds":["E03:4"],"topic":"이 양(쓸 수 있는 햇빛 에너지)은 2009년에 사람들이 쓴 화석 연료와 원자력 에너지를 모두 합한 양의 8,200배나 된다."},{"id":"E03:5","text":"태양 복사를 에너지로 사용하는 방법에는 태양열을 직접 흡수해서 물을 데우거나 난방으로 사용하는 방법, 태양열 발전소를 이용하는 방법, 그리고 태양 전지를 만들어 사용하는 방법이 있다.","paragraph":0,"memberIds":["E03:5"],"topic":"햇빛(태양 복사)을 에너지로 쓰는 방법은 세 가지이다. ① 태양열을 바로 받아서(직접 흡수해서) 물을 데우거나 난방에 쓰는 방법, ② 태양열 발전소를 이용하는 방법, ③ 태양 전지를 만들어 쓰는 방법이다."},{"id":"E03:6","text":"태양 전지는 태양 에너지를 직접 전기로 변환하는 장치로, 가장 이상적인 에너지 변환 장치 중 하나라고 할 수 있다.","paragraph":0,"memberIds":["E03:6"],"topic":"태양 전지는 태양 에너지를 곧바로 전기로 바꾸는 장치이다. 그래서 가장 바람직한(이상적인) 에너지 변환 장치 중 하나라고 할 수 있다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"E03:1","text":"이제 인류는 공존을 위해 기존의 화석 에너지를 대체할 방법으로 재생 에너지를 사용하려고 한다."},{"id":"E03:3","text":"이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다."},{"id":"E03:4","text":"이 양은 2009년 기준으로 전체 화석 연료와 원자력 에너지 사용량의 8,200배에 해당한다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U61-H03-05-B1","type":"ox","answer":"O","changed":"인류는 공존을 위해 화석 에너지 대신 재생 에너지, 그중에서도 쓸 수 있는 양이 많은 햇빛을 이용하려 한다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"3문단의 핵심","hintGuide":"3문단 첫 문장의 방향과 햇빛을 강조한 까닭을 함께 보세요.","synthesis":true,"editorSourceVersion":"93a651cbc26bacf6cb40d03a613f02dd5d28340f0d30c57fe82ccff275ccd1a9"}]},{"name":"U61-H04-03-B1 · 태양 전지의 재료","items":[{"paragraphCount":1,"readingLabel":"4문단 · 핵심 읽기 3/5단계","sourceLabel":"김효정, 「재생과 공존」 읽기 · 4문단","passage":"[핵심 문장 · 4문단]\n현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중 실리콘으로 만든다.\n근거: “현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다.”","evidence":{"title":"태양 전지의 재료","statement":"현재 태양 전지는 대부분 금속이 아닌 반도체 물질로 만든다.","explanation":"현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중 실리콘으로 만든다.\n근거: “현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다.”","valid":["E04:3"],"sources":[{"id":"E04","title":"김효정, 「재생과 공존」 읽기","label":"4문단","sentences":[{"id":"E04:3","text":"현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다.","paragraph":0,"memberIds":["E04:3"],"topic":"지금 태양 전지는 대부분 금속이 아닌 반도체 물질로 만든다. 그중에서도 지구에서 두 번째로 많은(풍부한) 물질인 실리콘을 쓴다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"E04:3","text":"현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U61-H04-03-B1","type":"ox","answer":"O","changed":"현재 태양 전지는 대부분 금속이 아닌 반도체 물질로 만든다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":3,"progressiveTotal":5,"progressiveLabel":"정보 구별","learningFocus":"태양 전지의 재료","hintGuide":"금속과 반도체 가운데 무엇으로 만드는지 보세요.","synthesis":false,"editorSourceVersion":"ecbbc13ed2e3ba3fe2c535a0e708c3e5c1dc5ccdbf8965fd37917ccac446ff69"}]},{"name":"U61-H04-05-B1 · 4문단의 핵심","items":[{"paragraphCount":1,"readingLabel":"4문단 · 핵심 읽기 5/5단계","sourceLabel":"김효정, 「재생과 공존」 읽기 · 4문단","passage":"[문단 전체 · 4문단]\n태양 전지는 광전 효과라는 것을 이용해서 태양 빛을 전기로 변환한다. 광전 효과는 충분한 에너지, 즉 일정 에너지 이상의 빛을 금속이나 반도체 물질에 가하면 움직일 수 있는 전자가 생성되는 현상을 의미한다. 현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다. 실리콘을 이용해서 만든 태양 전지는 태양광 패널 형태로 아파트 베란다나 도로변, 주차장 등에 설치되어 있다. 가정에서는 필요한 전력의 일부를 태양광 패널에서 만드는 전력으로부터 얻을 수 있다. 고속도로 휴게소 주차장에 설치된 태양광 패널을 보는 것도 더 이상 낯설지 않은 일이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"4문단은 태양 전지의 원리와 재료를 설명하고, 태양광 패널이 주변에 흔하다고 보여 준다.\n근거: “태양 전지는 광전 효과라는 것을 이용해서 태양 빛을 전기로 변환한다.” “현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다.” “실리콘을 이용해서 만든 태양 전지는 태양광 패널 형태로 아파트 베란다나 도로변, 주차장 등에 설치되어 있다.” “고속도로 휴게소 주차장에 설치된 태양광 패널을 보는 것도 더 이상 낯설지 않은 일이다.”","evidence":{"title":"4문단의 핵심","statement":"태양 전지는 광전 효과를 이용하며, 실리콘으로 만든 태양광 패널은 이미 우리 주변 곳곳에서 쓰인다.","explanation":"4문단은 태양 전지의 원리와 재료를 설명하고, 태양광 패널이 주변에 흔하다고 보여 준다.\n근거: “태양 전지는 광전 효과라는 것을 이용해서 태양 빛을 전기로 변환한다.” “현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다.” “실리콘을 이용해서 만든 태양 전지는 태양광 패널 형태로 아파트 베란다나 도로변, 주차장 등에 설치되어 있다.” “고속도로 휴게소 주차장에 설치된 태양광 패널을 보는 것도 더 이상 낯설지 않은 일이다.”","valid":["E04:1","E04:3","E04:4","E04:6"],"sources":[{"id":"E04","title":"김효정, 「재생과 공존」 읽기","label":"4문단","sentences":[{"id":"E04:1","text":"태양 전지는 광전 효과라는 것을 이용해서 태양 빛을 전기로 변환한다.","paragraph":0,"memberIds":["E04:1"],"topic":"태양 전지는 '광전 효과'라는 현상을 이용해서 태양 빛을 전기로 바꾼다."},{"id":"E04:2","text":"광전 효과는 충분한 에너지, 즉 일정 에너지 이상의 빛을 금속이나 반도체 물질에 가하면 움직일 수 있는 전자가 생성되는 현상을 의미한다.","paragraph":0,"memberIds":["E04:2"],"topic":"광전 효과는 에너지가 충분한 빛, 다시 말해 일정한 에너지 이상인 빛을 금속이나 반도체 물질에 비추면(가하면) 움직일 수 있는 전자가 생기는 현상이다."},{"id":"E04:3","text":"현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다.","paragraph":0,"memberIds":["E04:3"],"topic":"지금 태양 전지는 대부분 금속이 아닌 반도체 물질로 만든다. 그중에서도 지구에서 두 번째로 많은(풍부한) 물질인 실리콘을 쓴다."},{"id":"E04:4","text":"실리콘을 이용해서 만든 태양 전지는 태양광 패널 형태로 아파트 베란다나 도로변, 주차장 등에 설치되어 있다.","paragraph":0,"memberIds":["E04:4"],"topic":"실리콘으로 만든 태양 전지는 넓적한 판(태양광 패널) 모양으로 아파트 베란다, 길가(도로변), 주차장 같은 곳에 설치되어 있다."},{"id":"E04:5","text":"가정에서는 필요한 전력의 일부를 태양광 패널에서 만드는 전력으로부터 얻을 수 있다.","paragraph":0,"memberIds":["E04:5"],"topic":"집에서는 필요한 전기의 일부를 태양광 패널이 만든 전기로 얻을 수 있다."},{"id":"E04:6","text":"고속도로 휴게소 주차장에 설치된 태양광 패널을 보는 것도 더 이상 낯설지 않은 일이다.","paragraph":0,"memberIds":["E04:6"],"topic":"고속도로 휴게소 주차장에 있는 태양광 패널도 이제는 흔히 볼 수 있다(더 이상 낯설지 않다)."}]}]},"shortComparison":true,"focusQuotes":[{"id":"E04:1","text":"태양 전지는 광전 효과라는 것을 이용해서 태양 빛을 전기로 변환한다."},{"id":"E04:3","text":"현재 태양 전지의 대부분은 금속이 아닌 반도체 물질, 그중에서 지구에서 두 번째로 풍부한 물질인 실리콘을 이용해서 만들고 있다."},{"id":"E04:4","text":"실리콘을 이용해서 만든 태양 전지는 태양광 패널 형태로 아파트 베란다나 도로변, 주차장 등에 설치되어 있다."},{"id":"E04:6","text":"고속도로 휴게소 주차장에 설치된 태양광 패널을 보는 것도 더 이상 낯설지 않은 일이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U61-H04-05-B1","type":"ox","answer":"O","changed":"태양 전지는 광전 효과를 이용하며, 실리콘으로 만든 태양광 패널은 이미 우리 주변 곳곳에서 쓰인다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"4문단의 핵심","hintGuide":"원리, 재료, 쓰이는 곳의 순서로 4문단을 정리해 보세요.","synthesis":true,"editorSourceVersion":"c5dc8bfd2ef3a88824bdef2d2663d2cbd186bef1fe8b60c4478aace2307b4948"}]},{"name":"U61-E03-B1 · 비교","items":[{"paragraphCount":2,"readingLabel":"3문단 · 새 예시 적용","sourceLabel":"김효정, 「재생과 공존」 읽기 · 3문단","passage":"[김효정, 「재생과 공존」 읽기 · 3문단]\n이제 인류는 공존을 위해 기존의 화석 에너지를 대체할 방법으로 재생 에너지를 사용하려고 한다. 재생 에너지는 재생이 가능한 에너지로서 햇빛, 물, 지열, 강수, 생물 유기체 등에 포함된 에너지를 변환해 이용하는 에너지를 말한다. 이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다. 이 양은 2009년 기준으로 전체 화석 연료와 원자력 에너지 사용량의 8,200배에 해당한다. 태양 복사를 에너지로 사용하는 방법에는 태양열을 직접 흡수해서 물을 데우거나 난방으로 사용하는 방법, 태양열 발전소를 이용하는 방법, 그리고 태양 전지를 만들어 사용하는 방법이 있다. 태양 전지는 태양 에너지를 직접 전기로 변환하는 장치로, 가장 이상적인 에너지 변환 장치 중 하나라고 할 수 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n한여름에 도윤이가 마당에 둔 호스로 물을 틀었더니 햇볕에 직접 데워진 따뜻한 물이 나왔다. 마당의 정원등은 낮에 등 위의 작은 판으로 햇빛을 받아 전기를 만들어 두었다가, 밤이 되면 그 전기로 불을 켠다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit61","skills":["비교"],"why":"햇볕에 데워진 호스 속 물은 태양열을 직접 흡수해 물을 데우는 방법에, 햇빛으로 전기를 만드는 작은 판은 태양 에너지를 직접 전기로 변환하는 태양 전지에 대응한다.\n근거: “태양 복사를 에너지로 사용하는 방법에는 태양열을 직접 흡수해서 물을 데우거나 난방으로 사용하는 방법, 태양열 발전소를 이용하는 방법, 그리고 태양 전지를 만들어 사용하는 방법이 있다.” “태양 전지는 태양 에너지를 직접 전기로 변환하는 장치로, 가장 이상적인 에너지 변환 장치 중 하나라고 할 수 있다.”\n3문단에서 확인할 수 있어요.","evidence":{"title":"마당의 호스 물과 정원등","statement":"정원등의 작은 판은 햇빛을 직접 전기로 바꾸는 태양 전지에 해당한다.","explanation":"햇볕에 데워진 호스 속 물은 태양열을 직접 흡수해 물을 데우는 방법에, 햇빛으로 전기를 만드는 작은 판은 태양 에너지를 직접 전기로 변환하는 태양 전지에 대응한다.\n근거: “태양 복사를 에너지로 사용하는 방법에는 태양열을 직접 흡수해서 물을 데우거나 난방으로 사용하는 방법, 태양열 발전소를 이용하는 방법, 그리고 태양 전지를 만들어 사용하는 방법이 있다.” “태양 전지는 태양 에너지를 직접 전기로 변환하는 장치로, 가장 이상적인 에너지 변환 장치 중 하나라고 할 수 있다.”\n3문단에서 확인할 수 있어요.","valid":["E03:5","E03:6"],"sources":[{"id":"E03","title":"김효정, 「재생과 공존」 읽기","label":"3문단","sentences":[{"id":"E03:1","text":"이제 인류는 공존을 위해 기존의 화석 에너지를 대체할 방법으로 재생 에너지를 사용하려고 한다.","paragraph":0,"memberIds":["E03:1"],"topic":"이제 사람들은 지구와 함께 살아가기(공존) 위해, 지금까지 써 온 화석 에너지를 대신할 방법으로 재생 에너지를 쓰려고 한다."},{"id":"E03:2","text":"재생 에너지는 재생이 가능한 에너지로서 햇빛, 물, 지열, 강수, 생물 유기체 등에 포함된 에너지를 변환해 이용하는 에너지를 말한다.","paragraph":0,"memberIds":["E03:2"],"topic":"재생 에너지는 다시 생겨날 수 있는(재생이 가능한) 에너지이다. 햇빛, 물, 땅속의 열(지열), 비·눈(강수), 생물(생물 유기체) 등에 들어 있는 에너지를 바꾸어(변환해) 쓰는 에너지를 말한다."},{"id":"E03:3","text":"이 중에서도 햇빛, 즉 지구에 도달하는 태양 복사 에너지는 약 30 %가 우주로 다시 반사되고 나머지 70 % 정도를 사용할 수 있는 매우 매력적인 재생 에너지라고 할 수 있다.","paragraph":0,"memberIds":["E03:3"],"topic":"그중에서도 햇빛, 다시 말해 지구에 도착하는 태양 복사 에너지는 약 30 %가 우주로 다시 튕겨 나가고(반사되고) 나머지 70 % 정도를 쓸 수 있다. 그래서 아주 매력적인 재생 에너지라고 할 수 있다."},{"id":"E03:4","text":"이 양은 2009년 기준으로 전체 화석 연료와 원자력 에너지 사용량의 8,200배에 해당한다.","paragraph":0,"memberIds":["E03:4"],"topic":"이 양(쓸 수 있는 햇빛 에너지)은 2009년에 사람들이 쓴 화석 연료와 원자력 에너지를 모두 합한 양의 8,200배나 된다."},{"id":"E03:5","text":"태양 복사를 에너지로 사용하는 방법에는 태양열을 직접 흡수해서 물을 데우거나 난방으로 사용하는 방법, 태양열 발전소를 이용하는 방법, 그리고 태양 전지를 만들어 사용하는 방법이 있다.","paragraph":0,"memberIds":["E03:5"],"topic":"햇빛(태양 복사)을 에너지로 쓰는 방법은 세 가지이다. ① 태양열을 바로 받아서(직접 흡수해서) 물을 데우거나 난방에 쓰는 방법, ② 태양열 발전소를 이용하는 방법, ③ 태양 전지를 만들어 쓰는 방법이다."},{"id":"E03:6","text":"태양 전지는 태양 에너지를 직접 전기로 변환하는 장치로, 가장 이상적인 에너지 변환 장치 중 하나라고 할 수 있다.","paragraph":0,"memberIds":["E03:6"],"topic":"태양 전지는 태양 에너지를 곧바로 전기로 바꾸는 장치이다. 그래서 가장 바람직한(이상적인) 에너지 변환 장치 중 하나라고 할 수 있다."}]}]},"examplePractice":true,"id":"U61-E03-B1","type":"ox","answer":"O","changed":"정원등의 작은 판은 햇빛을 직접 전기로 바꾸는 태양 전지에 해당한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"2aec2b974df1582a7e0a4b8769b79a0ed68105538d852056d5bffca91c3cd81b"}]}]};})(window);
